'use strict';

// MODULES //

var isSignalReference = require( '@stdlib/plot/vega/base/assert/is-signal-reference' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var copyJSON = require( './../../utils/copy_json.js' );
var signalName = require( './../../utils/signal_name.js' );


// VARIABLES //

var PROPS = [
	'clipHeight',
	'columnPadding',
	'columns',
	'cornerRadius',
	'fill',
	'fillColor',
	'format',
	'formatType',
	'gradientLength',
	'gradientOpacity',
	'gradientStrokeColor',
	'gradientStrokeWidth',
	'gradientThickness',
	'gridAlign',
	'labelAlign',
	'labelBaseline',
	'labelColor',
	'labelFont',
	'labelFontSize',
	'labelFontStyle',
	'labelFontWeight',
	'labelLimit',
	'labelOffset',
	'labelOpacity',
	'labelOverlap',
	'labelSeparation',
	'legendX',
	'legendY',
	'offset',
	'opacity',
	'orient',
	'padding',
	'rowPadding',
	'shape',
	'size',
	'stroke',
	'strokeColor',
	'strokeDash',
	'strokeWidth',
	'symbolDash',
	'symbolDashOffset',
	'symbolFillColor',
	'symbolLimit',
	'symbolOffset',
	'symbolOpacity',
	'symbolSize',
	'symbolStrokeColor',
	'symbolStrokeWidth',
	'symbolType',
	'tickCount',
	'tickMinStep',
	'title',
	'titleAlign',
	'titleAnchor',
	'titleColor',
	'titleFont',
	'titleFontSize',
	'titleFontStyle',
	'titleFontWeight',
	'titleLimit',
	'titleLineHeight',
	'titleOpacity',
	'titleOrient',
	'titlePadding',
	'values',
	'zindex'
];

// Define a list of properties which need to be made explicitly "undefined" when set to falsy values:
var SPECIAL_PROPS = [
	'clipHeight',
	'columns',
	'cornerRadius',
	'fill',
	'format',
	'formatType',
	'labelAlign',
	'labelBaseline',
	'labelOverlap',
	'legendX',
	'legendY',
	'opacity',
	'shape',
	'size',
	'stroke',
	'strokeDash',
	'strokeWidth',
	'tickCount',
	'titleBaseline',
	'values'
];
var isSpecialProp = contains( SPECIAL_PROPS );


// MAIN //

/**
* Returns a transformed legend schema containing signals for use in conjunction with UI components.
*
* ## Notes
*
* -   The function mutates the provided list of signals.
*
* @private
* @param {Object} schema - legend schema
* @param {Array} signals - list of signals
* @param {Object} defaults - legend schema defaults
* @param {string} prefix - signal prefix
* @returns {Object} transformed schema
*/
function transform( schema, signals, defaults, prefix ) {
	var value;
	var name;
	var out;
	var k;
	var v;
	var i;

	out = copyJSON( schema );
	for ( i = 0; i < PROPS.length; i++ ) {
		k = PROPS[ i ];
		v = schema[ k ];
		if ( !isSignalReference( v ) ) {
			name = signalName( prefix+k );
			value = ( isUndefined( v ) ) ? defaults[ k ].default : v;

			if ( isSpecialProp( k ) ) {
				if ( isUndefined( v ) || v === '' || v === false ) {
					out[ k ] = void 0;
					signals.push({
						'name': name,
						'value': void 0
					});

					// Skip further processing...
					continue;
				}
			}
			signals.push({
				'name': name,
				'value': value
			});
			out[ k ] = value;
		}
	}
	// FIXME: Currently, Vega's `ariaGuide` reads `description` from `item.description` (the child visual item), not from `mark.description` (the group definition). Since `buildLegendEncode` does not map `description`, the value is never populated on the item and the custom description is silently ignored. As a workaround, inject the description via a custom `encode.legend.enter` mapping so that Vega copies it onto the visual item during initialization.
	if ( schema.description ) {
		// TODO: consider replacing the following logic with a call to `utils/deep-set` once refactored
		if ( !out.encode ) {
			out.encode = {};
		}
		if ( !out.encode.legend ) {
			out.encode.legend = {};
		}
		if ( !out.encode.legend.enter ) {
			out.encode.legend.enter = {};
		}
		out.encode.legend.enter.description = {
			'value': schema.description
		};
	} else if (
		out.encode &&
		out.encode.legend &&
		out.encode.legend.enter
	) {
		// TODO: determine whether it is possible to avoid using `delete` in order to avoid engine de-optimization
		delete out.encode.legend.enter.description;
	}
	return out;
}


// EXPORTS //

module.exports = transform;
